COMMON = r'''
import torch, ctypes, math, sys
import torch.nn.functional as F
class WSArgs(ctypes.Structure):
    _fields_ = [(n, ctypes.c_void_p) for n in ['x','dww','dwb','lnw','lnb','w1','b1','gw','gb','w2','b2','out','ws','stamps']] + [(n, ctypes.c_int) for n in 'BCHW'] + [('eps', ctypes.c_float), ('ln_eps', ctypes.c_float)]
def gen(B,C,H,W):
    d='cuda'
    x=torch.randn(B,C,H,W,device=d); dw=torch.randn(C,1,7,7,device=d)/math.sqrt(7); dwb=torch.randn(C,device=d)
    lnw=torch.ones(C,device=d); lnb=torch.zeros(C,device=d)
    w1=torch.randn(4*C,C,device=d)/math.sqrt(C); b1=torch.randn(4*C,device=d)
    gw=torch.randn(1,1,1,4*C,device=d)/math.sqrt(4*C); gb=torch.randn(1,1,1,4*C,device=d)
    w2=torch.randn(C,4*C,device=d)/math.sqrt(4*C); b2=torch.randn(C,device=d)
    return [x,dw,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2]
def ref(x,dw,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,eps=1e-6,lne=1e-6):
    C=x.shape[1]
    d=F.conv2d(x,dw,dwb,padding=3,groups=C).permute(0,2,3,1)
    a=F.layer_norm(d,(C,),lnw,lnb,lne)
    h=F.gelu(a@w1.T+b1)
    gx=torch.norm(h,p=2,dim=(1,2),keepdim=True); nx=gx/(gx.mean(dim=-1,keepdim=True)+eps)
    h=gw*(h*nx)+gb+h
    return x+(h@w2.T+b2).permute(0,3,1,2)
def load(p):
    l = ctypes.CDLL(p); l.ws_launch.restype = ctypes.c_void_p; l.ws_workspace_bytes.restype = ctypes.c_longlong; return l
def make_fn(lib, stamps=None):
    def fn(x,dw,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,out):
        B,C,H,W = x.shape
        ws = torch.empty(lib.ws_workspace_bytes(B,C,H,W), dtype=torch.uint8, device='cuda')
        a = WSArgs(*[t.data_ptr() for t in (x,dw,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,out,ws)], stamps.data_ptr() if stamps is not None else None, B,C,H,W, 1e-6, 1e-6)
        r = lib.ws_launch(ctypes.byref(a), ctypes.c_void_p(torch.cuda.current_stream().cuda_stream))
        if r: raise RuntimeError(ctypes.string_at(r))
    return fn
ROWS=[(2,768,7,7,2.6e-3),(8,768,7,7,2.9e-3),(16,768,7,7,2.9e-3),(32,768,7,7,2.9e-3),(8,384,14,14,2.8e-3),(16,384,14,14,3.3e-3)]
'''
open(f'{D}/common.py','w').write(COMMON)
STAMPS = r'''
import sys; sys.path.insert(0,'/tmp/d6e')
from common import *
import b200probe
lib = load(sys.argv[1])
names = {2:'s1',4:'G1epi',7:'s2',9:'G2epi'}
for (B,C,H,W,at) in ROWS:
    torch.manual_seed(1); ins = gen(B,C,H,W); out = torch.zeros_like(ins[0])
    st = torch.zeros(148*24, dtype=torch.int64, device='cuda'); fn = make_fn(lib, st)
    fn(*ins, out); torch.cuda.synchronize(); b200probe.flush_l2(); fn(*ins, out); torch.cuda.synchronize()
    s = st.view(148,24).cpu().double(); base = s[:,0].min()
    line = f'{B},{C},{H*W}: '
    for i in [2,4,7,9]:
        v = s[:,i]; v = v[v>0]
        if len(v): line += f'{names[i]} {(v-base).median().item()/1e3:.1f}/{(v-base).max().item()/1e3:.1f} '
    line += '| dur med/max: '
    for i,nm in [(11,'g1pre'),(12,'g1wait'),(13,'g1post')]:
        v = s[:,i]; line += f'{nm} {v.median().item()/1e3:.1f}/{v.max().item()/1e3:.1f} '
    print(line, flush=True)
'''
open(f'{D}/stamps.py','w').write(STAMPS)
TIME = r'''
